  int[] active=s.activeRange();int activeStart=s.current==null?-1:Math.max(0,active[0]-start),activeEnd=s.current==null?-1:Math.min(end-start,active[1]-start);if(activeStart!=highlightStart||activeEnd!=highlightEnd){Spannable text=(Spannable)passage.getText();if(highlight!=null)text.removeSpan(highlight);highlightStart=activeStart;highlightEnd=activeEnd;if(activeStart>=0&&activeEnd>activeStart){highlight=new ForegroundColorSpan(readerInk);text.setSpan(highlight,activeStart,activeEnd,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}}
