 void settings(){ListenService service=ListenService.live;String speed=service==null?"1":String.format(Locale.US,"%.2g",service.speed);new AppDialog.Builder(this).setTitle("Listen settings").setItems(new String[]{"Speed · "+speed+"×","Sleep timer","Text and spacing","Follow spoken text · "+(follow?"On":"Off"),"Narrator voice","Equalizer & voice gain","Stop listening"},(d,n)->{if(n==0)speed();else if(n==1)timer();else if(n==2)EpubTypography.show(this,this::typography);else if(n==3){follow=!follow;holdFollowUntil=0;lastFollowLine=-1;getSharedPreferences("listen",0).edit().putBoolean("follow",follow).apply();render();}else if(n==4)Listen.voiceSettings(this);else if(n==5)Listen.effects(this);else{if(ListenService.live!=null)ListenService.live.stop();finish();}}).setNegativeButton("Close",null).show();}
